import{_ as e,o as a,c as l,ao as r}from"./chunks/framework.AQkxRU0n.js";const p=JSON.parse('{"title":"Colmat.jl マニュアル","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),d={name:"index.md"};function o(i,t,n,s,c,f){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="Colmat.jl-マニュアル" tabindex="-1">Colmat.jl マニュアル <a class="header-anchor" href="#Colmat.jl-マニュアル" aria-label="Permalink to &quot;Colmat.jl マニュアル {#Colmat.jl-マニュアル}&quot;">​</a></h1><p>Colmat.jlは、Rustの <a href="https://github.com/tensor4all/faer" target="_blank" rel="noreferrer">colmat</a>を Julia から使う線形代数パッケージです。Juliaの配列や <code>LinearAlgebra</code>に慣れていれば、行列の積や連立方程式から使い始められます。分解の公式を覚えている必要はありません。</p><h2 id="最初に読むページ" tabindex="-1">最初に読むページ <a class="header-anchor" href="#最初に読むページ" aria-label="Permalink to &quot;最初に読むページ {#最初に読むページ}&quot;">​</a></h2><ol><li><p><a href="./installation">インストールと最初の計算</a>で <code>A * x</code>と <code>A \\ b</code>を試します。</p></li><li><p><a href="./getting-started">計算の選び方と用語</a>で、自分の問題に合う関数を選びます。</p></li><li><p><a href="./manual/arrays">配列・型・所有権</a>で Julia 配列との変換やビューを確認します。</p></li></ol><p>通常の配列は Juliaの GCに管理を任せられます。例ごとに <code>close</code>を並べる必要はありません。解放時期を指定したい場合は<a href="./manual/lifetimes">GCと資源の寿命</a>の <code>do</code> ブロックを使ってください。</p><h2 id="目的から探す" tabindex="-1">目的から探す <a class="header-anchor" href="#目的から探す" aria-label="Permalink to &quot;目的から探す {#目的から探す}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">したいこと</th><th style="text-align:left;">ページ</th></tr></thead><tbody><tr><td style="text-align:left;">連立方程式・最小二乗問題を解く、分解を保存する</td><td style="text-align:left;"><a href="./manual/dense">密行列の分解と求解</a></td></tr><tr><td style="text-align:left;">固有値・固有ベクトルを計算する</td><td style="text-align:left;"><a href="./manual/spectral">固有値・Schur・QZ</a></td></tr><tr><td style="text-align:left;">ゼロが多い行列を扱う</td><td style="text-align:left;"><a href="./manual/sparse">疎行列と直接法</a></td></tr><tr><td style="text-align:left;">疎行列の最小二乗・最小ノルム問題を解く</td><td style="text-align:left;"><a href="./manual/sparse-qr">疎 QR</a></td></tr><tr><td style="text-align:left;">大きな問題を反復的に解く、行列を作らず積を定義する</td><td style="text-align:left;"><a href="./manual/operators">線形作用素・反復法</a></td></tr><tr><td style="text-align:left;">分解の内部で使う反射・回転・縮約を扱う</td><td style="text-align:left;"><a href="./manual/reductions">反射・回転・縮約</a></td></tr><tr><td style="text-align:left;">一時メモリや計算スレッドを再利用する</td><td style="text-align:left;"><a href="./manual/resources">作業領域とチーム</a></td></tr><tr><td style="text-align:left;">平均・分散、乱数、NumPy ファイルを使う</td><td style="text-align:left;"><a href="./manual/utilities">統計・乱数・NPY</a></td></tr></tbody></table><p>関数名から探す場合は <a href="./reference/api">API 案内</a>、ビルドやテストは<a href="./development">開発ガイド</a>を参照してください。各マニュアルの後半は、性能調整や内部の格納形式が必要になったときに読む詳細です。</p><h2 id="共通の約束" tabindex="-1">共通の約束 <a class="header-anchor" href="#共通の約束" aria-label="Permalink to &quot;共通の約束 {#共通の約束}&quot;">​</a></h2><p>Rust 側で直接計算する数値型は <code>Float32</code>・<code>Float64</code>・<code>ComplexF32</code>・<code>ComplexF64</code>です。添字と置換は Juliaと同じく 1 から数えます。明示的な構築・変換は通常コピーを作り、ビューは元の配列を保持します。</p><p>関数名の <code>!</code>は引数の更新を示します。どの値を書き込むか、結果と入力がメモリを共有するかは関数によって異なります。元の値が必要ならコピーしてから実行してください。</p><p><code>scratch=</code>は一時メモリ、<code>team=</code>は計算スレッドの指定です。初めは省略して構いません。作業領域を渡しても返り値などのメモリは別に確保し、チームを渡しても逐次実行する処理があります。</p>',12)])])}const m=e(d,[["render",o]]);export{p as __pageData,m as default};
